            KTP_PARTITION_FLAG_DOCX_TABLE_1_REQUIRED_ALL_COL: state.docx_table_1_required_all,
            KTP_PARTITION_FLAG_DOCX_ANY_COL: state.docx_any,
            "card_subset_mode": subset_mode,
